// Tile sizes
#define TILE_N 16
#define TILE_M 16

// Number of doubles per 512-bit word
#define DOUBLES_PER_WORD 8

static void load_tile_C_wide(
    ap_uint<512>* C_wide,
    double tileC[TILE_N][TILE_N],
    int i_base, int j_base,
    int tile_rows, int tile_cols)
{
    for (int i = 0; i < tile_rows; i++) {
