#include <ap_int.h>

// Tile sizes
#define TILE_N 16
#define TILE_M 16

// Number of doubles per 512-bit word (512 / 64 = 8)
#define DOUBLES_PER_WORD 8

// Helper: read doubles from wide bus into local array
static void wide_bus_read_double(
    double* dst,
    ap_uint<512>* src,
    int byte_offset,
    int num_bytes)
{
    int num_doubles = num_bytes / sizeof(double);
    // byte_offset must be aligned to double (8 bytes)
    int start_double = byte_offset / sizeof(double);
    int start_word = start_double / DOUBLES_PER_WORD;
    int start_lane = start_double % DOUBLES_PER_WORD;

    int d = 0;
    int word_idx = start_word;
    int lane = start_lane;

    read_loop: for (int d = 0; d < num_doubles; d++) {
#pragma HLS PIPELINE II=1
        int wi = (start_double + d) / DOUBLES_PER_WORD;
        int li = (start_double + d) % DOUBLES_PER_WORD;
        ap_uint<512> word = src[wi];
        ap_uint<64> bits = word.range(li * 64 + 63, li * 64);
        double val;
        *((ap_uint<64>*)(&val)) = bits;
        dst[d] = val;
    }
}

// Helper: write doubles from local array to wide bus
static void wide_bus_write_double(
    ap_uint<512>* dst,
    double* src,
    int byte_offset,
    int num_bytes)
{
    int num_doubles = num_bytes / sizeof(double);
    int start_double = byte_offset / sizeof(double);

    write_loop: for (int d = 0; d < num_doubles; d++) {
#pragma HLS PIPELINE II=1
        int wi = (start_double + d) / DOUBLES_PER_WORD;
        int li = (start_double + d) % DOUBLES_PER_WORD;
        ap_uint<512> word = dst[wi];
        double val = src[d];
        ap_uint<64> bits = *((ap_uint<64>*)(&val));
        word.range(li * 64 + 63, li * 64) = bits;
        dst[wi] = word;
    }
}

